# 最小割 = 最大流 + 残量网络可达性标记。以下依赖 dinic 节点的 Dinic 类。
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
    def add_edge(self, u, v, cap):
        self.adj[u].append([v, cap, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])
    def _bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v, cap, rev in self.adj[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] >= 0
    def _dfs(self, u, t, f):
        if u == t:
            return f
        while self.it[u] < len(self.adj[u]):
            e = self.adj[u][self.it[u]]
            v, cap, rev = e
            if cap > 0 and self.level[v] == self.level[u] + 1:
                pushed = self._dfs(v, t, min(f, cap))
                if pushed:
                    e[1] -= pushed
                    self.adj[v][rev][1] += pushed
                    return pushed
            self.it[u] += 1
        return 0
    def max_flow(self, s, t):
        flow = 0
        INF = 10 ** 18
        while self._bfs(s, t):
            self.it = [0] * self.n
            while True:
                pushed = self._dfs(s, t, INF)
                if not pushed:
                    break
                flow += pushed
        return flow
    def min_cut_set(self, s):
        """返回残量网络中 s 可达的点集（最小割 S* 侧）."""
        vis = [False] * self.n
        vis[s] = True
        stack = [s]
        while stack:
            u = stack.pop()
            for v, cap, rev in self.adj[u]:
                if cap > 0 and not vis[v]:
                    vis[v] = True
                    stack.append(v)
        return vis


if __name__ == "__main__":
    # 图: s=0,t=3; 0->1(3) 0->2(3) 1->2(2) 1->3(3) 2->3(3); 最大流=最小割=6
    g = Dinic(4)
    g.add_edge(0, 1, 3); g.add_edge(0, 2, 3)
    g.add_edge(1, 2, 2); g.add_edge(1, 3, 3); g.add_edge(2, 3, 3)
    flow = g.max_flow(0, 3)
    S = g.min_cut_set(0)
    # 割边 = u in S, v not in S
    cut_edges = []
    for u in range(4):
        for v, cap, rev in g.adj[u]:
            if S[u] and not S[v]:
                cut_edges.append((u, v))
    print("maxflow =", flow)
    print("S =", [i for i in range(4) if S[i]])
    print("cut_edges =", cut_edges)
    assert flow == 6
